```typescript
p.rule("myrule", (r) => {
    r.display("My custom rule");
    r.fileExtension(".in");

    r.propertyDefinition({
        name: "myoption",
        display: "My option",
        description: "Select the option to use",
        values: { 0: "option1", 1: "option2"},
