    r.buildMessage("custom rule: {copy} %{file.relpath} %{file.basename}");
    r.buildOutputs("%{sln.location}/%{file.basename}");
    r.buildCommands("MyScript {myoption} %[%{!file.abspath}] %[%{!sln.location}/%{file.basename}]");

});
